{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name, metric, round(avg(value),3) avgv, round(max(value),3) maxv FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'geo%' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY ALL", "claim": "Geo pod stays not-ready (ready avg 0) through the window while restarting about 5 times on average (max 6); normal period shows 0 restarts."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='geo' GROUP BY ALL", "claim": "Geo emits no spans at all in the abnormal window, versus 669 geo.Geo/Nearby server spans in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, quantile_cont(duration,0.5)/1e6 med_ms FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' GROUP BY ALL", "claim": "Search's calls to geo.Geo/Nearby all return Error in about 0.015 ms median, meaning fast connection failure."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name parent_svc, p.span_name parent_span, p.attr_status_code parent_status, c.service_name child_svc, c.span_name child_span, c.attr_status_code child_status, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.service_name IN ('search','geo') GROUP BY ALL ORDER BY n DESC LIMIT 5", "claim": "Within the same traces, search's server span search.Search/Nearby is Error on every geo.Geo/Nearby child that is Error (622 pairs)."}
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name parent_svc, p.span_name parent_span, p.attr_status_code parent_status, c.service_name child_svc, c.span_name child_span, c.attr_status_code child_status, count(*) n FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='frontend' AND p.span_name='HTTP /hotels' GROUP BY ALL", "claim": "Frontend HTTP /hotels server spans return 500 Error (680 of them) with the failing search.Search/Nearby call beneath them."}
      ]
    }
  ]
}
